const items = $input.all();

const results = [];

for (let i = 0; i < items.length; i++) {
  const current = items[i].json;

  const historical = items
    .slice(0, i)
    .map(item => Number(item.json.revenue));

  let baseline_avg = null;
  let baseline_std = null;
  let z_score = null;
  let anomaly = false;

  if (historical.length >= 2) {
    baseline_avg =
      historical.reduce((sum, value) => sum + value, 0) /
      historical.length;

    const variance =
      historical.reduce(
        (sum, value) => sum + Math.pow(value - baseline_avg, 2),
        0
      ) / historical.length;

    baseline_std = Math.sqrt(variance);

    if (baseline_std > 0) {
      z_score =
        (Number(current.revenue) - baseline_avg) /
        baseline_std;

      anomaly = Math.abs(z_score) > 2;
    }
  }

  results.push({
    json: {
      ...current,
      baseline_avg:
        baseline_avg === null
          ? null
          : Math.round(baseline_avg * 100) / 100,

      baseline_std:
        baseline_std === null
          ? null
          : Math.round(baseline_std * 100) / 100,

      z_score:
        z_score === null
          ? null
          : Math.round(z_score * 100) / 100,

      anomaly
    }
  });
}

return results;

const items = $input.all();

const orderCounts = {};

for (const item of items) {
  const orderId = String(item.json.order_id).trim();

  orderCounts[orderId] = (orderCounts[orderId] || 0) + 1;
}

return items.map(item => {
  const row = item.json;
  const issues = [];

  // Missing customer ID
  if (!row.customer_id || String(row.customer_id).trim() === '') {
    issues.push('Missing customer ID');
  }

  // Invalid date
  const date = new Date(row.order_date);

  if (isNaN(date.getTime())) {
    issues.push('Invalid order date');
  }

  // Revenue validation
  const revenue = Number(row.revenue);

  if (isNaN(revenue)) {
    issues.push('Invalid revenue');
  } else if (revenue < 0) {
    issues.push('Negative revenue');
  }

  // Duplicate order ID
  const orderId = String(row.order_id).trim();

  if (orderCounts[orderId] > 1) {
    issues.push('Duplicate order ID');
  }

  // Missing product ID
  if (!row.product_id || String(row.product_id).trim() === '') {
    issues.push('Missing product ID');
  }

  return {
    json: {
      ...row,
      valid: issues.length === 0,
      issues
    }
  };
});

const items = $input.all();

const weeks = items
  .map(item => item.json)
  .sort((a, b) => a.week.localeCompare(b.week));

// We need at least 2 weeks for week-over-week comparison
if (weeks.length < 2) {
  return [
    {
      json: {
        status: 'INSUFFICIENT_DATA',
        message: 'Not enough weekly data to perform the analysis.',
        weeks_available: weeks.length
      }
    }
  ];
}

const latest = weeks[weeks.length - 1];
const previous = weeks[weeks.length - 2];

// Previous week's revenue
const previousRevenue = Number(previous.revenue);

// Order growth
const orderGrowth =
  Number(previous.orders) > 0
    ? ((Number(latest.orders) - Number(previous.orders)) /
        Number(previous.orders)) * 100
    : null;

// Historical revenue
const historicalRevenues = weeks
  .slice(0, -1)
  .map(week => Number(week.revenue));

const historicalAverage =
  historicalRevenues.reduce((sum, value) => sum + value, 0) /
  historicalRevenues.length;

// Compare latest week against historical average
const vsHistoricalAverage =
  ((Number(latest.revenue) - historicalAverage) /
    historicalAverage) * 100;

// Observations
const observations = [];

if (latest.anomaly) {
  observations.push(
    `Revenue is significantly outside the historical baseline (z-score: ${latest.z_score}).`
  );
}

if (
  latest.revenue_growth !== null &&
  latest.revenue_growth > 0
) {
  observations.push(
    `Revenue increased ${latest.revenue_growth}% compared with the previous week.`
  );
} else if (
  latest.revenue_growth !== null &&
  latest.revenue_growth < 0
) {
  observations.push(
    `Revenue decreased ${Math.abs(latest.revenue_growth)}% compared with the previous week.`
  );
}

if (orderGrowth > 0) {
  observations.push(
    `Orders increased ${Math.round(orderGrowth * 100) / 100}% compared with the previous week.`
  );
} else if (orderGrowth < 0) {
  observations.push(
    `Orders decreased ${Math.abs(Math.round(orderGrowth * 100) / 100)}% compared with the previous week.`
  );
}

if (vsHistoricalAverage > 0) {
  observations.push(
    `Revenue is ${Math.round(vsHistoricalAverage * 100) / 100}% above the historical average.`
  );
} else {
  observations.push(
    `Revenue is ${Math.abs(Math.round(vsHistoricalAverage * 100) / 100)}% below the historical average.`
  );
}

return [
  {
    json: {
      status: 'SUCCESS',
      week: latest.week,
      revenue: Number(latest.revenue),
      orders: Number(latest.orders),
      previous_revenue: previousRevenue,

      revenue_growth:
        latest.revenue_growth,

      order_growth:
        orderGrowth === null
          ? null
          : Math.round(orderGrowth * 100) / 100,

      historical_average:
        Math.round(historicalAverage * 100) / 100,

      vs_historical_average:
        Math.round(vsHistoricalAverage * 100) / 100,

      baseline_avg: latest.baseline_avg,
      baseline_std: latest.baseline_std,
      z_score: latest.z_score,
      anomaly: latest.anomaly,

      observations
    }
  }
];

const text = $json.text;

// Verified values from the Analyst
const revenue = Number($('Analyst — Weekly Insights').item.json.revenue);
const revenueGrowth = Number($('Analyst — Weekly Insights').item.json.revenue_growth);
const zScore = Number($('Analyst — Weekly Insights').item.json.z_score);
const historicalAverage = Number(
  $('Analyst — Weekly Insights').item.json.historical_average
);

// Check whether the generated text contains the verified values
const checks = {
  revenue: text.includes(String(revenue)),
  revenue_growth: text.includes(String(revenueGrowth)),
  z_score: text.includes(String(zScore)),
  historical_average: text.includes(String(historicalAverage))
};

const passed = Object.values(checks).every(Boolean);

return {
  json: {
    narration: text,
    quality_check: passed ? 'PASS' : 'FAIL',
    checks
  }
};

const data = $json;

if (data.quality_check !== 'PASS') {
  return [];
}

const analyst = $('Analyst — Weekly Insights').item.json;

const powerBIUrl = 'https://app.powerbi.com/links/k1jO83FdAu?ctid=c161ec3a-f23b-463b-823e-79329dc7b3f9&pbi_source=linkShare';

return {
  json: {
    report_message:
      `Weekly Sales Report — ${analyst.week}\n\n` +
      `${data.narration}\n\n` +
      `Quality Check: PASS\n\n` +
      `Power BI Report: ${powerBIUrl}`
  }
};

const items = $input.all();

const invalidRows = items.filter(
  item => item.json.valid === false
);

const issueCounts = {};

for (const item of invalidRows) {
  for (const issue of item.json.issues || []) {
    issueCounts[issue] = (issueCounts[issue] || 0) + 1;
  }
}

const issueSummary = Object.entries(issueCounts)
  .map(([issue, count]) => `${issue}: ${count}`)
  .join('\n');

return [
  {
    json: {
      status: 'DATA_QUALITY_FAILED',
      invalid_records: invalidRows.length,
      issue_summary: issueSummary,
      message:
        `Data quality validation failed. ` +
        `${invalidRows.length} invalid record(s) detected.\n\n` +
        issueSummary
    }
  }
];

const items = $input.all();

const weekly = {};

for (const item of items) {
  const date = new Date(item.json.order_date);
  const revenue = Number(item.json.revenue);

  const day = date.getUTCDay();
  const daysFromMonday = day === 0 ? 6 : day - 1;

  date.setUTCDate(date.getUTCDate() - daysFromMonday);

  const week = date.toISOString().split('T')[0];

  if (!weekly[week]) {
    weekly[week] = {
      week,
      revenue: 0,
      orders: 0
    };
  }

  weekly[week].revenue += revenue;
  weekly[week].orders += 1;
}

const results = Object.values(weekly).sort(
  (a, b) => a.week.localeCompare(b.week)
);

return results.map((current, index) => {
  const previous = results[index - 1];

  const revenueGrowth = previous
    ? ((current.revenue - previous.revenue) / previous.revenue) * 100
    : null;

  return {
    json: {
      week: current.week,
      revenue: Math.round(current.revenue * 100) / 100,
      orders: current.orders,
      revenue_growth: revenueGrowth === null
        ? null
        : Math.round(revenueGrowth * 100) / 100
    }
  };
});
